"""Generate the evaluation summary from the committed model card."""
from __future__ import annotations

import argparse
import json
from pathlib import Path


BACKEND = Path(__file__).resolve().parents[1]
ROOT = BACKEND.parent
MODEL_CARD = BACKEND / "app" / "ml" / "models" / "model_card.json"
OUTPUT = ROOT / "docs" / "EVALUATION.md"


def generate() -> str:
    card = json.loads(MODEL_CARD.read_text(encoding="utf-8"))
    policy = card["policy_eval_synthetic"]
    lines = [
        "# Model evaluation",
        "",
        "<!-- Generated by narcotrace-backend/scripts/generate_evaluation.py; do not edit by hand. -->",
        "",
        f"**Status:** {card['status']}",
        "",
        "All reported values below are from the committed model card and are synthetic-only.",
        "They are not estimates of field performance or real-lab accuracy.",
        "",
        "| Metric | Value |",
        "| --- | ---: |",
        f"| Calibrated test accuracy | {card['test_accuracy_synthetic'] * 100:.1f}% |",
        f"| Calibrated accuracy when card found | {card['test_accuracy_synthetic_card_found'] * 100:.1f}% |",
        f"| Raw uncalibrated baseline accuracy | {card['test_accuracy_synthetic_raw_uncalibrated_baseline'] * 100:.1f}% |",
        f"| Decision-policy definite-answer coverage | {policy['coverage'] * 100:.1f}% |",
        f"| Correct among definite answers | {policy['correct_when_definite'] * 100:.1f}% |",
        "",
        "## Per-class metrics",
        "",
        "| Synthetic class | Precision | Recall | F1 |",
        "| --- | ---: | ---: | ---: |",
    ]
    for label, metrics in card["per_class"].items():
        lines.append(
            f"| `{label}` | {metrics['precision'] * 100:.1f}% | "
            f"{metrics['recall'] * 100:.1f}% | {metrics['f1-score'] * 100:.1f}% |"
        )
    lines.extend(["", "## Limitations", ""])
    lines.extend(f"- {limitation}" for limitation in card["limitations"])
    lines.extend([
        "- Real-photo validation has not been run; production status must remain synthetic baseline.",
        "- Kit-chart verification and legal review are separate release gates.",
        "",
    ])
    return "\n".join(lines)


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    content = generate()
    if args.check:
        if not OUTPUT.exists() or OUTPUT.read_text(encoding="utf-8") != content:
            raise SystemExit("docs/EVALUATION.md is stale; rerun the generator")
        print("docs/EVALUATION.md matches the committed model card.")
        return
    OUTPUT.write_text(content, encoding="utf-8")
    print(f"Wrote {OUTPUT}")


if __name__ == "__main__":
    main()
